// WF14 triage config v0.2 (PATCH). Deterministic ids; MSK timestamps; NO external calls, NO Claude (DEC-130).
// Bounded scope to prevent Google Sheets quota / item explosion: capped source rows + capped writes.
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const stamp=moscowStamp();
return [{ json: {
  // ---- scope / bounds (quota safety; DEC-130 patch)
  time_window_days:30,
  max_source_rows:100,            // working candidate pool cap (applied AFTER score/sort/filter)
  max_signals_to_write:25,        // hard ceiling on appended rows
  platform_filter:'',             // '' = any; operator may set 'vk'
  source_type_filter:'',          // '' = any
  include_queue_tabs:['review_queue'], // primary analyzed source; raw is secondary enrichment
  only_untriaged:true,
  backfill_untriaged:true,        // allow older untriaged high-score rows when fresh window is thin
  min_signal_score:50,
  // ---- contact / outreach policy (CONTACT_AND_OUTREACH_POLICY: evidence, NOT permission)
  contact_use_policy_default:'aggregate_only',
  contact_use_policy_with_public_contact:'manual_review',
  allowed_recommended_actions:['manual_review','content_idea','monitor'],
  forbidden_recommended_actions:['outreach','contact','dm','message','call','email'],
  region_default:'Москва/МО',
  requested_by:'operator',
  // ---- deterministic ids + MSK stamps
  run_stamp:stamp,
  run_id:'wf14_'+stamp,
  agent_request_id:'wf14_req_'+stamp,
  created_at:moscowIsoNow()
}}];

// Collapse to a single control item so the NEXT Google Sheets read executes EXACTLY ONCE.
// Prevents item explosion (a multi-item read feeding another read = read-per-item = quota error).
// Sheet data stays available downstream via $('Read ...').all().
return [{ json: $('Set Triage Config').first().json }];

// Collapse to a single control item so the NEXT Google Sheets read executes EXACTLY ONCE.
// Prevents item explosion (a multi-item read feeding another read = read-per-item = quota error).
// Sheet data stays available downstream via $('Read ...').all().
return [{ json: $('Set Triage Config').first().json }];

// WF14 BUILD CANDIDATE POOL + CLASSIFY — deterministic, $0, no Claude (DEC-130). PATCH: bounded scope, no item explosion.
// Each Sheet is read ONCE (upstream collapse nodes guarantee single execution); this node runs once for all items.
// Only PUBLIC evidence. A public profile/contact is EVIDENCE, never outreach permission (CONTACT_AND_OUTREACH_POLICY).
// recommended_action is constrained to {manual_review, content_idea, monitor}; outreach is impossible by construction.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function cut(s,n){s=str(s);return s.length>n?(s.slice(0,n-1)+'…'):s;}
function norm(s){return low(s).replace(/\s+/g,' ').trim().slice(0,200);}
function h32(s,seed){s=str(s);let h=seed>>>0;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return h;}
function lsidOf(platform,post_url,textNorm,intent){var base=low(platform)+'|'+low(post_url)+'|'+textNorm+'|'+low(intent);return 'pls_'+('0000000'+h32(base,5381).toString(16)).slice(-8)+('0000000'+h32(base,7919).toString(16)).slice(-8);}
function rows(name){try{return $(name).all().map(i=>i.json).filter(r=>r&&Object.keys(r).some(k=>str(r[k])!==''));}catch(e){return [];}}

const cfg=$('Set Triage Config').first().json;
const windowDays=Number(cfg.time_window_days)||30;
const cutoffMs=Date.now()-windowDays*86400000;
const maxSource=Math.max(1,Math.min(100,Number(cfg.max_source_rows)||100)); // hard ceiling 100
const maxWrite=Math.max(1,Math.min(25,Number(cfg.max_signals_to_write)||25)); // hard ceiling 25
const minScore=Number(cfg.min_signal_score)||0;
const platformFilter=low(cfg.platform_filter);
const sourceTypeFilter=low(cfg.source_type_filter);
const backfill=cfg.backfill_untriaged!==false;
const ALLOWED=Array.isArray(cfg.allowed_recommended_actions)?cfg.allowed_recommended_actions:['manual_review','content_idea','monitor'];
const FORBIDDEN=['outreach','contact','dm','message','call','email'];

const review=rows('Read review_queue');
const raw=rows('Read raw_market_records');
const existing=rows('Read public_lead_signals');

// dedup keys vs already-triaged signals: lead_signal_id (primary) + platform|post_url|text_evidence|intent_type (fallback)
const existIds=new Set(existing.map(r=>low(r.lead_signal_id)).filter(Boolean));
const existFallback=new Set(existing.map(r=>low(r.platform)+'|'+low(r.post_url)+'|'+norm(r.text_evidence)+'|'+low(r.intent_type)).filter(x=>x.replace(/\|/g,'').length>3));

// ---- vocabulary (DEC-130): keyword -> pain_type enum
const PAIN=[
 ['после отказ','after_refusal'],['отказали','after_refusal'],['отказ банка','after_refusal'],['отказов банк','after_refusal'],['банки отказ','after_refusal'],
 ['плохая кредитн','bad_credit_history'],['плохой кредитн','bad_credit_history'],['кредитная истори','bad_credit_history'],['плохая ки','bad_credit_history'],
 ['просрочк','overdue_debt'],['долг','overdue_debt'],
 ['срочно нужн','urgent_money_need'],['срочно деньги','urgent_money_need'],['горит','urgent_money_need'],
 ['предоплат','prepayment_fear'],
 ['мошенник','fraud_fear'],['обман','fraud_fear'],['кидал','fraud_fear'],['пропада','fraud_fear'],['развод','fraud_fear'],
 ['сколько стоит','broker_price_question'],['сколько это стоит','broker_price_question'],['какая комиссия','broker_price_question'],['процент брокер','broker_price_question'],
 ['ипотек','mortgage_refinance_need'],['рефинансир','mortgage_refinance_need'],['снизить ставк','mortgage_refinance_need'],
 ['для бизнеса','business_finance_need'],['ип и ооо','business_finance_need'],['оборотн','business_finance_need'],['тендерн','business_finance_need']
];
const QUESTION=['подскажите','посоветуйте','кто брал','кто обращался','к кому обращаться','как получить','что делать','нужен совет','?'];
const OBJECTION=['мошенник','обман','кидал','пропада','не верю','развод','боюсь','предоплат'];
const COMPLAINT=['жалоб','обманули','кинули','не вернули','отвратительн'];
const BUY=['нужен кредит','нужен займ','нужна помощь с кредит','к кому обращаться','сколько это стоит','хочу взять','помогите получить','нужен совет'];

// ---- build candidate pool (review_queue primary; raw_market_records audience rows as secondary enrichment)
const cands=[];
function pushCand(o){
  if(platformFilter && low(o.platform)!==platformFilter) return;
  if(sourceTypeFilter && low(o.source_type)!==sourceTypeFilter) return;
  cands.push(o);
}
for(const r of review){
  pushCand({src:'review_queue',source_type:str(r.source_type),platform:low(r.platform),
    source_url:str(r.source_url),post_url:str(r.post_url)||str(r.source_url),
    profile_url:str(r.profile_url),profile_name:str(r.profile_name),author_handle:str(r.author_handle),
    region:str(r.region),service_need:str(r.service_type)||str(r.detected_need),
    text:[str(r.text_context),str(r.detected_need),str(r.reason)].filter(Boolean).join(' || '),
    contact_public:str(r.contact_public),contact_channel:str(r.contact_channel),
    created_at:str(r.created_at)||str(r.observed_at),
    proc:low(r.processing_status)});
}
for(const r of raw){
  const tpt=low(r.touchpoint_type);const rth=low(r.record_type_hint);
  const isAudience=(rth==='question_objection')||['public_comment','forum_discussion','review_source'].indexOf(tpt)>=0;
  if(!isAudience)continue;
  const ds=low(r.dedup_status);
  if(ds.indexOf('duplicate')===0||ds==='hard_skipped'||ds==='invalid')continue;
  const ps=low(r.processing_status);
  if(ps&&(ps.indexOf('fail')>=0||ps.indexOf('error')>=0))continue;
  pushCand({src:'raw_market_records',source_type:str(r.source_type),platform:low(r.platform),
    source_url:str(r.source_url),post_url:str(r.post_url)||str(r.source_url),
    profile_url:str(r.profile_url),profile_name:str(r.profile_name),author_handle:str(r.author_handle),
    region:str(r.region_hint)||str(r.region),service_need:str(r.service_hint)||str(r.probable_need),
    text:[str(r.comment_text),str(r.text_context)].filter(Boolean).join(' || '),
    contact_public:str(r.contact_public),contact_channel:str(r.contact_channel),
    created_at:str(r.created_at)||str(r.observed_at),
    proc:ps});
}

// ---- classify + score + dedup
let dupSkipped=0, irrelevant=0;
const seenBatch=new Set();
const scored=[];
for(const c of cands){
  const blob=low(c.text);
  if(blob.length<25){irrelevant++;continue;}
  const pains=[];for(const p of PAIN){if(blob.indexOf(p[0])>=0&&pains.indexOf(p[1])<0)pains.push(p[1]);}
  const qHit=QUESTION.filter(t=>blob.indexOf(t)>=0).length;
  const objHit=OBJECTION.filter(t=>blob.indexOf(t)>=0).length;
  const compHit=COMPLAINT.filter(t=>blob.indexOf(t)>=0).length;
  const buyHit=BUY.filter(t=>blob.indexOf(t)>=0).length;
  if(!pains.length&&!qHit&&!objHit&&!buyHit){irrelevant++;continue;}
  // intent_type enum: question / objection / complaint / buying_intent / content_signal
  let intent='content_signal';
  if(buyHit&&qHit)intent='buying_intent';
  else if(compHit)intent='complaint';
  else if(objHit&&!qHit)intent='objection';
  else if(qHit)intent='question';
  else if(buyHit)intent='buying_intent';
  const urgency=Math.min(100,(blob.indexOf('срочно')>=0?60:0)+(pains.indexOf('urgent_money_need')>=0?30:0)+(buyHit?20:10));
  const intentScore=Math.min(100,buyHit*30+qHit*15+(pains.length?15:0));
  const objScore=Math.min(100,objHit*25+compHit*15);
  const signalScore=Math.max(intentScore,objScore,urgency);
  if(signalScore<minScore){irrelevant++;continue;}
  const tnorm=norm(c.text);
  const lsid=lsidOf(c.platform,c.post_url,tnorm,intent);
  const fb=low(c.platform)+'|'+low(c.post_url)+'|'+norm(cut(c.text,300))+'|'+low(intent);
  if(existIds.has(low(lsid))||existFallback.has(fb)||seenBatch.has(lsid)){dupSkipped++;continue;}
  seenBatch.add(lsid);
  const tsN=Date.parse(c.created_at); const fresh=!isNaN(tsN)&&tsN>=cutoffMs;
  if(!fresh && !backfill){irrelevant++;continue;}
  scored.push({c,pains,intent,urgency,intentScore,objScore,signalScore,lsid,fresh,ts:isNaN(tsN)?0:tsN,qHit,objHit,compHit,buyHit});
}

// untriaged-first is implicit (dups already removed); rank fresh -> higher signal score -> newer
scored.sort((a,b)=>{
  if(a.fresh!==b.fresh)return a.fresh?-1:1;
  if(b.signalScore!==a.signalScore)return b.signalScore-a.signalScore;
  return (b.ts||0)-(a.ts||0);
});
const afterFilters=scored.length;
const pool=scored.slice(0,maxSource);   // source cap AFTER score/sort/filter
const chosen=pool.slice(0,maxWrite);    // hard write cap (<=25)

const out=[];
for(const s of chosen){
  const c=s.c;
  const hasContact=!!str(c.contact_public);
  // Sheets formula/#ERROR! fix (DEC-124): leading +/= forced to text
  const safeContact=/^[+=]/.test(str(c.contact_public))?("'"+str(c.contact_public)):str(c.contact_public);
  const painLabel=s.pains.join(', ')||'unclassified_pain';
  let action=(s.intent==='buying_intent'||s.intent==='question')?'manual_review':((s.intent==='objection'||s.intent==='complaint')?'content_idea':'monitor');
  if(ALLOWED.indexOf(action)<0||FORBIDDEN.indexOf(action)>=0)action='manual_review'; // never outreach
  let policy=hasContact?str(cfg.contact_use_policy_with_public_contact||'manual_review'):str(cfg.contact_use_policy_default||'aggregate_only');
  if(policy!=='manual_review'&&policy!=='aggregate_only')policy='aggregate_only';
  out.push({ json:{
    lead_signal_id:s.lsid,
    created_at:str(cfg.created_at),
    source_type:c.source_type||'unknown',
    platform:c.platform||'unknown',
    source_url:c.source_url,
    post_url:c.post_url,
    profile_url:c.profile_url,            // public-only by upstream contract; evidence, NOT outreach permission
    profile_name:c.profile_name,
    author_handle:c.author_handle,
    public_identity_label:(c.profile_name||c.author_handle)?'public_profile_visible':'no_public_identity',
    region:c.region||str(cfg.region_default),
    service_need:c.service_need||'unknown',
    text_evidence:cut(c.text,300),
    pain_type:painLabel,
    intent_type:s.intent,
    urgency_score:s.urgency,
    intent_score:s.intentScore,
    objection_score:s.objScore,
    contact_public:safeContact,
    contact_channel:str(c.contact_channel),
    contact_use_policy:policy,
    recommended_action:action,
    status:'new',
    source_confidence:(c.src==='review_queue'?55:50)+(s.pains.length>=2?10:0),
    evidence_note:'pains: '+painLabel+'; q='+s.qHit+'; obj='+s.objHit+'; comp='+s.compHit+'; buy='+s.buyHit+'; src='+c.src+'; signal_score='+s.signalScore,
    agent_request_id:str(cfg.agent_request_id),
    run_id:str(cfg.run_id),
    notes:'wf14 deterministic triage (DEC-130); text_hash='+h32(norm(c.text),5381).toString(16)+'; public evidence only; profile_url/contact = evidence, NOT outreach permission; never auto-outreach.'
  }});
}

// expose run stats for downstream summary/agent_requests without polluting the append payload
const sd=$getWorkflowStaticData('global');
sd.wf14_run={
  rows_read_review_queue:review.length,
  rows_read_raw_market_records:raw.length,
  rows_read_existing_public_lead_signals:existing.length,
  rows_after_filters:afterFilters,
  candidate_signals:afterFilters,
  duplicates_skipped:dupSkipped,
  irrelevant_skipped:irrelevant,
  signals_written:out.length,
  max_source_rows:maxSource,
  max_signals_to_write:maxWrite
};

if(!out.length){
  return [{ json:{ _no_signals:true, rows_after_filters:afterFilters, candidate_signals:afterFilters, duplicates_skipped:dupSkipped, irrelevant_skipped:irrelevant } }];
}
return out;

// One agent_requests row (exactly 21 columns). status=completed. $0, no external calls, no Claude.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Triage Config').first().json;
const items=$('Build Candidate Pool & Classify').all().map(i=>i.json);
const noSignals=items.length===1&&items[0]._no_signals===true;
const signals=noSignals?[]:items;
const sd=$getWorkflowStaticData('global');const st=sd.wf14_run||{};
const byIntent={};for(const s of signals){const k=str(s.intent_type)||'unknown';byIntent[k]=(byIntent[k]||0)+1;}
const withContact=signals.filter(s=>str(s.contact_public)).length;
const dup=(typeof st.duplicates_skipped==='number')?st.duplicates_skipped:0;
return [{ json: {
  agent_request_id:str(cfg.agent_request_id),
  created_at:str(cfg.created_at),
  requested_by:str(cfg.requested_by)||'operator',
  request_type:'public_lead_signal_triage',
  request_text:'Bounded deterministic triage of public audience comments/questions/reviews into public_lead_signals (window '+(Number(cfg.time_window_days)||30)+'d; max_source_rows='+(Number(cfg.max_source_rows)||100)+'; max_write='+Math.min(25,Number(cfg.max_signals_to_write)||25)+')',
  source_scope:'business_queues',
  platforms:str(cfg.platform_filter)||'all',
  query:'review_queue (primary) + raw_market_records audience rows (secondary), scored/deduped/capped',
  region:str(cfg.region_default)||'Москва/МО',
  service_focus:'credit_brokerage',
  requested_limit:Math.min(25,Number(cfg.max_signals_to_write)||25),
  status:'completed',
  plan_summary:'WF14 Public Lead Signal Triage v0.2 (DEC-130 patch): single-read tabs + bounded candidate pool + dedup + capped append into public_lead_signals (28 cols). No Claude, no external calls, no outreach; contact_use_policy=manual_review/aggregate_only.',
  estimated_source_cost_usd:0,
  estimated_analysis_cost_usd:0,
  approval_required:false,
  approved_by:'',
  approved_at:'',
  result_summary:(noSignals?'no_signals; ':'')+'signals_written='+signals.length+'; duplicates_skipped='+dup+'; by_intent='+JSON.stringify(byIntent)+'; with_public_contact='+withContact+'; contact_use_policy=manual_review (with contact) / aggregate_only; outreach=forbidden.',
  next_action:(signals.length?'Manager: review public_lead_signals rows with status=new; confirm/dismiss classification. NO outreach — public profile/contact is evidence, not permission (CONTACT_AND_OUTREACH_POLICY).':'No new public lead signals; run source connectors + WF08 first, widen time_window_days, or lower min_signal_score.'),
  notes:'wf14 v0.2 deterministic; reads review_queue + raw_market_records ONCE each; writes public_lead_signals + agent_requests only; never auto-outreach; no private chats; no member extraction; no hidden contacts.'
}}];

// Final run summary (Task G). No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Triage Config').first().json;
const items=$('Build Candidate Pool & Classify').all().map(i=>i.json);
const noSignals=items.length===1&&items[0]._no_signals===true;
const signals=noSignals?[]:items;
const sd=$getWorkflowStaticData('global');const st=sd.wf14_run||{};
function pick(k,fb){return (typeof st[k]==='number')?st[k]:fb;}
const reviewN=pick('rows_read_review_queue',$('Read review_queue').all().length);
const rawN=pick('rows_read_raw_market_records',$('Read raw_market_records').all().length);
const existN=pick('rows_read_existing_public_lead_signals',$('Read public_lead_signals').all().length);
// --- Task F: WF14 read-once / cap / dedup self-test (DEC-131). No external calls.
const _cap=Math.min(25,Number(cfg.max_signals_to_write)||25);
const _dupSkipped=pick('duplicates_skipped',0);
const _readOnce={review_queue:(typeof reviewN==='number'),raw_market_records:(typeof rawN==='number'),public_lead_signals:(typeof existN==='number')};
const _capOk=(signals.length<=_cap);
const _readOnceOk=(_readOnce.review_queue&&_readOnce.raw_market_records&&_readOnce.public_lead_signals);
const _selfTestPassed=_capOk&&_readOnceOk;
let status='completed';
if(!str(cfg.run_id))status='failed_validation';
else if(!signals.length)status='completed_no_data';
return [{ json: {
  workflow:'14 - Public Lead Signal Triage (Deterministic)',
  run_id:str(cfg.run_id),
  agent_request_id:str(cfg.agent_request_id),
  rows_read_review_queue:reviewN,
  rows_read_raw_market_records:rawN,
  rows_read_existing_public_lead_signals:existN,
  rows_after_filters:pick('rows_after_filters',signals.length),
  candidate_signals:pick('candidate_signals',signals.length),
  duplicates_skipped:pick('duplicates_skipped',0),
  signals_written:signals.length,
  max_source_rows:Math.min(100,Number(cfg.max_source_rows)||100),
  max_signals_to_write:Math.min(25,Number(cfg.max_signals_to_write)||25),
  claude_calls:0,
  external_calls:0,
  cost_usd:0,
  status:status,
  next_action:(signals.length?'Manager: review status=new rows in public_lead_signals; confirm/dismiss. NO outreach (CONTACT_AND_OUTREACH_POLICY).':'No new public lead signals; run connectors + WF08 first, widen time_window_days, or lower min_signal_score.'),
  read_once_ok:_readOnceOk,
  append_cap:_cap,
  append_cap_ok:_capOk,
  duplicates_skipped_check:_dupSkipped,
  self_test_passed:_selfTestPassed,
  health_check:'read-once[review_queue,raw_market_records,public_lead_signals]='+_readOnceOk+'; signals_written='+signals.length+'<=cap('+_cap+')='+_capOk+'; duplicates_skipped='+_dupSkipped+'; repeat runs should write 0 new + duplicates_skipped>0'
}}];
